code_sketch:
char *line = NULL; size_t cap = 0; ssize_t n;
uint32_t seq = 0;
while ((n = getdelim(&line, &cap, '\n', in)) != -1) {
    struct part p = { .corr = corr, .seq = seq++, .len = (size_t)n };
    memcpy(p.body, line, (size_t)n);   /* copy: line is reused by the next read */
    publish_part(broker, &p);          /* one message per record */
}
free(line);
publish_end_marker(broker, corr, seq); /* parts are complete */
